module Prob_8_16_STR (output [15: 0] PR, output done,input [7: 0] data_AR, data_BR, input  start, clock, reset_b);Controller_P8_16 M0 (done, Ld_regs, Add_decr, start, zero, clock, reset_b); Datapath_P8_16 M1 (PR, zero, data_AR, data_BR, Ld_regs, Add_decr, clock, reset_b);endmodulemodule Controller_P8_16 (output done, output reg Ld_regs, Add_decr, input start, zero, clock, reset_b);parameter  s0 = 1'b0, s1 = 1'b1;reg state, next_state;assign done = (state == s0);always @ (posedge clock, negedge reset_b)if (!reset_b) state <= s0; else state <= next_state;always @ (state, start, zero) beginLd_regs = 0;Add_decr = 0;case (state)s0:		if (start) begin Ld_regs = 1; next_state = s1; ends1:		if (zero) next_state = s0; else  begin next_state = s1; Add_decr = 1; enddefault:	next_state = s0;endcaseendendmodulemodule Register_32 (output [31: 0] data_out, input [31: 0] data_in, input clock, reset_b);Register_8 M3 (data_out [31: 24] , data_in  [31: 24], clock, reset_b);Register_8 M2 (data_out [23: 16] , data_in  [23: 16], clock, reset_b);Register_8 M1 (data_out [15: 8] , data_in  [15: 8], clock, reset_b);Register_8 M0 (data_out [7: 0] , data_in  [7: 0], clock, reset_b);endmodulemodule Register_16 (output [15: 0] data_out, input [15: 0] data_in, input clock, reset_b);Register_8 M1 (data_out [15: 8] , data_in  [15: 8], clock, reset_b);Register_8 M0 (data_out [7: 0] , data_in  [7: 0], clock, reset_b);endmodulemodule Register_8 (output [7: 0] data_out, input [7: 0] data_in, input clock, reset_b);D_flop M7 (data_out[7] data_in[7], clock, reset_b);D_flop M6 (data_out[6] data_in[6], clock, reset_b);D_flop M5 (data_out[5] data_in[5], clock, reset_b);D_flop M4 (data_out[4] data_in[4], clock, reset_b);D_flop M3 (data_out[3] data_in[3], clock, reset_b);D_flop M2 (data_out[2] data_in[2], clock, reset_b);D_flop M1 (data_out[1] data_in[1], clock, reset_b);D_flop M0 (data_out[0] data_in[0], clock, reset_b);endmodulemodule Adder_32 (output c_out, output [31: 0]  sum, input [31: 0] a, b);assign {c_out, sum} = a + b;endmodulemodule Adder_16 (output c_out, output [15: 0] sum, input [15: 0] a, b);assign {c_out, sum} = a + b;endmodule
module D_flop (output q, input data, clock, reset_b);always @ (posedge clock, negedge reset_b)if (!reset_b) q <= 0; else q <= data;endmodulemodule  Datapath_P8_16 (output reg [15: 0] PR, output zero,input [7: 0] data_AR, data_BR, input Ld_regs, Add_decr, clock, reset_b);reg [7: 0]	AR, BR;assign 	zero = ~( | AR);always @ (posedge clock, negedge reset_b)if (!reset_b) begin AR <= 8'b0; BR <= 8'b0; PR <= 16'b0; endelse beginif (Ld_regs) begin AR <= data_AR; BR <= data_BR; PR <= 0; endelse if (Add_decr) begin PR <= PR + BR; AR <= AR -1; endendendmodule// Test plan Ð Verify;// Power-up reset// Data is loaded correctly// Control signals assert correctly// Status signals assert correctly// start is ignored while multiplying// Multiplication is correct// Recovery from reset on-the-flymodule t_Prob_P8_16;wire 		done;wire [15: 0] 	PR;reg [7: 0] 	data_AR, data_BR;reg  		start, clock, reset_b;Prob_8_16_STR M0 (PR, done, data_AR, data_BR, start, clock, reset_b);initial #500 $finish;initial begin clock = 0; forever #5 clock = ~clock; endinitial forkreset_b = 0;#12 reset_b = 1;#40 reset_b = 0;#42 reset_b = 1;#90 reset_b = 1;#92 reset_b = 1;joininitial fork#20 start = 1;#30 start = 0;#40 start = 1;#50 start = 0;#120 start = 1;#120 start = 0;join
initial forkdata_AR = 8'd5;		// AR > 0data_BR = 8'd20;#80 data_AR = 8'd3;#80 data_BR = 8'd9;#100 data_AR = 8'd4;#100 data_BR = 8'd9;joinendmodule